mapper.select:
SELECT status

FROM shipments

WHERE shipment_id = #{shipmentId}

mapper.delete:
DELETE FROM shipments
WHERE shipment_id = #{shipmentId}
AND status = 'READY'

mapper.update:
UPDATE shipments
SET gateway_id = #{gatewayId},
driver_name = #{driverName},
driver_phone = CASE WHEN #{driverPhone} IS NOT NULL AND #{driverPhone} != '' THEN #{driverPhone}
ELSE driver_phone END,
updated_at = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
WHERE shipment_id = #{shipmentId}
AND vehicle_number = #{vehicleNumber}
AND status = 'READY'
AND gateway_id IS NULL
